def create_user(name, age):
    if not name or not name.strip():
        raise ValueError('name is required')
    if age < 0 or age > 150:
        raise ValueError('age is invalid')
    return {'name': name.strip(), 'age': age}

def update_user(user, name, age):
    if not name or not name.strip():
        raise ValueError('name is required')
    if age < 0 or age > 150:
        raise ValueError('age is invalid')
    user.update(name=name.strip(), age=age)
    return user

import pytest
from src.users import create_user, update_user

def test_create_and_update():
    assert create_user(' Ada ', 20) == {'name': 'Ada', 'age': 20}
    assert update_user({}, ' Bob ', 30) == {'name': 'Bob', 'age': 30}

@pytest.mark.parametrize('name,age', [('', 20), ('ok', -1), ('ok', 151)])
def test_create_rejects_invalid(name, age):
    with pytest.raises(ValueError):
        create_user(name, age)

